WITH with_last AS (SELECT s.*, x.store_sale_sale_date FROM products s JOIN LATERAL (SELECT c.sale_date AS store_sale_sale_date FROM store_sales c WHERE c.product_id = s.id ORDER BY c.revenue DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN price >= 1030 THEN 'HIGH' ELSE 'LOW' END AS price_tier, DATE_TRUNC('MONTH', store_sale_sale_date) AS activity_month, COUNT_IF(category = 'Sports') AS sports_events, APPROX_PERCENTILE(price, 0.5) AS price_p50 FROM with_last GROUP BY GROUPING SETS ((CASE WHEN price >= 1030 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('MONTH', store_sale_sale_date)), (CASE WHEN price >= 1030 THEN 'HIGH' ELSE 'LOW' END)) ORDER BY sports_events DESC;
